<include file="Public:header"/><div class="mainbox">    <div id="nav" class="mainnav_title">        <ul>            <a href="javascript:history.go(-1)" >上一级</a>            <a href="" class="on">优惠明细</a>        </ul>    </div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('Allinpay/discount_use')}" method="get">                    <input type="hidden" name="c" value="Allinpay"/>                    <input type="hidden" name="a" value="discount_use"/>                    <input type="hidden" name="id" value="{pigcms{$_GET['id']}"/>                    筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                    <select name="searchtype">                        <option value="order_id" <if condition="$_GET['searchtype'] eq 'order_id'">selected="selected"</if>>订单流水号</option>                        <option value="name" <if condition="$_GET['searchtype'] eq 'name'">selected="selected"</if>>订单名称</option>                    </select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                    <div style="display:inline"><font color="#000">时间筛选 ：</font></div>                    <input type="text" class="input" name="begin_time" id="d4311"  value="{pigcms{$begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>&nbsp;&nbsp;&nbsp;                    <input type="text" class="input" name="end_time" id="d4312" value="{pigcms{$end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>&nbsp;&nbsp;&nbsp;                    <input type="submit" value="查询" class="button"/>                    &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<b>总优惠金额：{pigcms{$total_discount_money}</b>&nbsp;&nbsp;&nbsp;&nbsp;<b>                </form>                <button><a href="{pigcms{:U('Allinpay/discount_export', $_REQUEST)}" >导出EXCEL</a></button>            </td>        </tr>    </table>    <form name="myform" id="myform" action="" method="post">        <div class="table-list">            <style>                .table-list td{line-height:22px;padding-top:5px;padding-bottom:5px;}            </style>            <table width="100%" cellspacing="0">                <colgroup>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col/>                    <col width="100" align="center"/>                </colgroup>                <thead>                <tr>                    <th>编号</th>                    <th>订单流水号</th>                    <th>业务类型</th>                    <th>商家名称</th>                    <th>订单名</th>                    <th>支付时间</th>                    <th>用户名</th>                    <th>订单金额</th>                    <th>优惠类型</th>                    <th>优惠金额</th>                    <th>实付金额</th>                </tr>                </thead>                <tbody>                <if condition="$list">                    <volist name="list" id="vo">                        <tr>                            <td>{pigcms{$vo.allinpay_order_id}</td>                            <td>{pigcms{$vo.order_id}</td>                            <td>{pigcms{$vo.business}</td>                            <td>{pigcms{$vo.name}</td>                            <td>{pigcms{$vo.order_name}</td>                            <td>{pigcms{$vo.pay_time|date="Y-m-d H:i:s",###}</td>                            <td>{pigcms{$vo.nickname}</td>                            <td>{pigcms{$vo['order_price']|floatval}</td>                            <td><if condition="$vo['discount_type'] eq 0">满减<elseif condition="$vo['discount_type'] eq 1" />折扣<else/>随机立减</if></td>                            <td>{pigcms{$vo['discount_money']|floatval}</td>                            <td>{pigcms{$vo['paid_money']|floatval}</td>                        </tr>                    </volist>                    <tr><td class="textcenter pagebar" colspan="11">{pigcms{$pagebar}</td></tr>                    <else/>                    <tr><td class="textcenter red" colspan="11">列表为空！</td></tr>                </if>                </tbody>            </table>        </div>    </form></div><include file="Public:footer"/>